            <input type="date" value={selectedDate} max={today}
              onChange={(e) => setSelectedDate(e.target.value)}
              style={{ background: "transparent", border: "none", outline: "none", color: "#1a1628", padding: "10px 12px", fontFamily: "'DM Sans', sans-serif", fontSize: "14px", width: "100%", boxSizing: "border-box", display: "block" }}
            />
